This is the filterable list: a segmented control for status above eight rows, each with a title, status badge and one-line detail. The catalog has no container component, so I used a single-column `columns` layout to stack the filter and the list.

The catalog also has no way to link the filter to the list. The control's `name` is `status_filter`, but nothing in this catalog makes it hide rows, so the host app has to apply the filter.

<a2ui-json>
[
  {
    "version": "v0.9.1",
    "createSurface": {
      "surfaceId": "status_list",
      "catalogId": "https://a2uicatalog.ai/catalog/c-data-display.json"
    }
  },
  {
    "version": "v0.9.1",
    "updateComponents": {
      "surfaceId": "status_list",
      "components": [
        {
          "id": "root",
          "component": "columns",
          "cols": 1,
          "gap": "1rem",
          "align": "stretch",
          "items": [
            {
              "blocks": [
                {
                  "component": "heading",
                  "id": "title",
                  "text": "Project Tasks"
                },
                {
                  "component": "segmented_control",
                  "id": "status_filter",
                  "name": "status_filter",
                  "selected_value": "all",
                  "options": [
                    { "label": "All", "value": "all" },
                    { "label": "Done", "value": "done" },
                    { "label": "In progress", "value": "in_progress" },
                    { "label": "Blocked", "value": "blocked" },
                    { "label": "Planned", "value": "planned" }
                  ]
                },
                {
                  "component": "entity_list",
                  "id": "items_list",
                  "items": [
                    { "name": "Set up CI pipeline", "subtitle": "Automated builds and tests run on every pull request.", "icon": "⚙️", "status": "Done" },
                    { "name": "Design system audit", "subtitle": "Reviewing component usage across all product screens.", "icon": "🎨", "status": "In progress" },
                    { "name": "Payment gateway integration", "subtitle": "Waiting on vendor API credentials to proceed.", "icon": "💳", "status": "Blocked" },
                    { "name": "User onboarding flow", "subtitle": "Three-step welcome tour with progress tracking.", "icon": "👋", "status": "In progress" },
                    { "name": "Database migration", "subtitle": "Move legacy tables to the new schema with zero downtime.", "icon": "🗄️", "status": "Planned" },
                    { "name": "Accessibility fixes", "subtitle": "Resolved all critical contrast and keyboard issues.", "icon": "♿", "status": "Done" },
                    { "name": "Analytics dashboard", "subtitle": "Draft KPI layout pending stakeholder sign-off.", "icon": "📊", "status": "Planned" },
                    { "name": "Email notifications", "subtitle": "Template rendering fails for some locales.", "icon": "✉️", "status": "Blocked" }
                  ]
                }
              ]
            }
          ]
        }
      ]
    }
  }
]
</a2ui-json>
